const TOKEN=<?php echo json_encode($token); ?>;const AUTH_HEADERS={'X-AVR-Worker-Token':TOKEN};const OWN_FLEET=<?php echo $isOwnFleet?'true':'false'; ?>;let online=false,watch=null,lastSent=0,lastPosition=null,currentWorker=null,currentOrders=[],driverOrderTab='free',teamMap=null,teamMarkers=[],partnerMarkers=[],photoPickerActive=false,photoPickerTimer=null,geoRequestId=0,geoStarting=false;const loadingPhotoFiles=new Map();
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=n=>Number(n||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';
const dateRu=v=>{if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})};
function showPanel(panel){document.querySelectorAll('.portalTab').forEach(x=>x.classList.toggle('active',x.dataset.panel===panel));document.querySelectorAll('.portalPanel').forEach(x=>x.classList.toggle('active',x.dataset.panelView===panel));if(panel==='team'){loadTeamMap();loadPartnerOrders()}if(panel==='finance'){loadFinance();loadLedger()}if(panel==='history')loadHistory();if(panel==='rating')loadRating();if(panel==='profile')loadProfileSummary();window.scrollTo({top:0,behavior:'smooth'})}
function openExtraPanel(panel){showPanel(panel);document.querySelectorAll('.portalTab').forEach(x=>x.classList.remove('active'))}
document.querySelectorAll('.portalTab').forEach(b=>b.onclick=()=>showPanel(b.dataset.panel));
document.querySelectorAll('[data-order-tab]').forEach(b=>b.onclick=()=>setDriverOrderTab(b.dataset.orderTab));
document.querySelectorAll('[data-finance-target]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-finance-target]').forEach(x=>x.classList.toggle('red',x===b));document.querySelectorAll('.financePane').forEach(x=>x.classList.toggle('active',x.id===b.dataset.financeTarget))});
async function loadHistory(){const box=document.getElementById('historyList');box.innerHTML='<span class="muted">Загрузка…</span>';try{const r=await fetch('/api/worker_history.php',{cache:'no-store',headers:AUTH_HEADERS}),d=await r.json();if(!r.ok||!d.ok)throw new Error('Не удалось загрузить историю');const rows=(d.orders||[]).slice().reverse();box.innerHTML=rows.length?rows.map(o=>{const f=o.financials||{};return `<div class="historyOrder"><div class="historyHead"><b>${esc(o.id)}</b><span>${esc(o.status==='completed'?'Выполнен':'Выполнен')}</span></div><div>${esc(o.service||'Заказ')} · ${esc(o.vehicle_type||'')}</div><div class="muted">${esc(o.address||'')}${o.destination?' → '+esc(o.destination):''}</div>${f.excluded?'<div class="profileNotice">MAX/B2B · отдельный расчёт</div>':`<div class="historyFinance"><span>Стоимость ${money(f.price||o.estimated_price||o.price||0)} · комиссия ${money(f.commission||0)}</span><b>Доход ${money(f.driver_net||0)}</b></div>`}<small class="muted">${dateRu(o.completed_at||o.updated_at||o.created_at||'')}</small></div>`}).join(''):'<div class="empty">Завершённых заказов пока нет</div>';document.getElementById('homeCompleted').textContent=String(rows.length)}catch(e){box.textContent=e.message||'Ошибка загрузки'}}
async function loadRating(){const summary=document.getElementById('ratingSummary'),reviews=document.getElementById('ratingReviews');summary.textContent='Загрузка…';try{const r=await fetch('/api/worker_rating_details.php?token='+encodeURIComponent(TOKEN),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось загрузить рейтинг');const p=d.profile||{},q=d.quality||{},dist=p.distribution||{},max=Math.max(1,...[1,2,3,4,5].map(n=>Number(dist[n]||0))),trend=Number(p.trend||0);summary.innerHTML=`<div class="ratingHero"><div><div class="ratingScore">★ ${Number(p.rating||5).toFixed(2)}</div><div class="muted">${esc(p.label||'')} · ${Number(p.count||0)} оценок</div><div class="muted">Последние ${Number(p.recent_count||0)}: ${Number(p.recent_average||5).toFixed(2)} · тренд ${trend>0?'+':''}${trend.toFixed(2)}</div></div><div class="ratingBars">${[5,4,3,2,1].map(n=>`<div class="ratingBar"><b>${n}★</b><div class="ratingTrack"><div class="ratingFill" style="width:${Math.round(Number(dist[n]||0)/max*100)}%"></div></div><span>${Number(dist[n]||0)}</span></div>`).join('')}</div></div><div class="financeGrid"><div class="metric"><small>Завершено заказов</small><b>${Number(q.completed_orders||0)}</b></div><div class="metric"><small>Получено оценок</small><b>${Number(q.rated_orders||0)}</b></div><div class="metric"><small>Отказы от предложений</small><b>${Number(q.rejected_offers||0)}</b></div></div>`;const rows=d.ratings||[];reviews.innerHTML=rows.length?rows.map(x=>`<div class="ratingReview"><div class="ratingReviewHead"><b class="ratingStars">${'★'.repeat(Number(x.score||0))}${'☆'.repeat(5-Number(x.score||0))}</b><small class="muted">${esc(x.created_at||'')}</small></div><div>${x.comment?esc(x.comment):'<span class="muted">Без комментария</span>'}</div><small class="muted">Заказ ${esc(x.order_id||'—')}</small></div>`).join(''):'<div class="empty">Оценок пока нет</div>'}catch(e){summary.textContent=e.message||'Ошибка загрузки';reviews.innerHTML=''}}
async function loadProfileSummary(){const box=document.getElementById('profileSummary'),docs=document.getElementById('profileDocsState');try{const r=await fetch('/api/mobile_executor_profile.php',{headers:{'X-AVR-Worker-Token':TOKEN},cache:'no-store',credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error('Не удалось загрузить профиль');const p=d.profile||{},docCount=Object.keys(p.documents||{}).length;box.innerHTML=`<div class="profileItem"><small>ФИО</small><b>${esc(p.name||'—')}</b></div><div class="profileItem"><small>Телефон</small><b>${esc(p.phone||'—')}</b></div><div class="profileItem"><small>Email</small><b>${esc(p.email||'—')}</b></div><div class="profileItem"><small>Техника</small><b>${esc(p.vehicle_type||'—')}</b></div><div class="profileItem"><small>Госномер</small><b>${esc(p.plate||'—')}</b></div><div class="profileItem"><small>Грузоподъёмность</small><b>${esc(p.capacity||'—')}</b></div><div class="profileItem"><small>Услуги</small><b>${esc((p.services||[]).join(', ')||'Не выбраны')}</b></div><div class="profileItem"><small>Модерация</small><b>${p.approved?'Подтверждён':p.review_status==='rejected'?'Требуются исправления':'На проверке'}</b></div>`;docs.textContent='Фотографии и документы: '+docCount+' из 9';docs.classList.toggle('good',docCount===9)}catch(e){box.textContent=e.message||'Ошибка загрузки';docs.textContent=''}}
function statusRu(s){return ({offline:'Офлайн',online:'На линии',reserved:'Есть новый заказ',busy:'Занят'})[s]||s}
function teamStatusRu(s){return ({online:'Свободен',reserved:'Получает заказ',busy:'На заказе'})[s]||s}
async function loadTeamMap(){
 if(!OWN_FLEET)return;
 const stateEl=document.getElementById('teamState'),mapEl=document.getElementById('teamMap'),listEl=document.getElementById('teamDrivers');
 try{
  const r=await fetch('api/worker_map.php',{cache:'no-store',headers:AUTH_HEADERS}),d=await r.json();
  if(!d.ok){stateEl.textContent=d.error==='OWN_FLEET_ONLY'?'Карта доступна только собственному автопарку.':(d.error||'Не удалось загрузить карту');mapEl.hidden=true;listEl.innerHTML='';return}
  if(!d.online){stateEl.textContent='Выйдите на линию, чтобы увидеть сменщиков.';mapEl.hidden=true;listEl.innerHTML='';return}
  const rows=d.workers||[];stateEl.textContent=rows.length?'Позиции обновляются автоматически.':'Сейчас на линии нет машин с актуальной геопозицией.';
  listEl.innerHTML=rows.map(w=>`<div class="driverRow"><div><b>${esc(w.name)}${w.is_self?' · вы':''}</b><span class="ownBadge">Наш парк</span><div class="driverMeta">${esc(w.vehicle_type)}${w.plate?' · '+esc(w.plate):''} · ${esc(teamStatusRu(w.status))}</div>${w.phone?`<div class="driverMeta"><a style="color:#ff747b" href="tel:${esc(w.phone)}">${esc(w.phone)}</a></div>`:''}</div><div class="driverEta">${w.is_self?'Ваша позиция':(w.distance_km===null?'':w.distance_km+' км · ≈ '+w.eta_min+' мин')}</div></div>`).join('');
  if(typeof ymaps==='undefined'||!rows.length){mapEl.hidden=true;return}
  mapEl.hidden=false;
  const self=rows.find(w=>w.is_self),center=self?[self.lat,self.lng]:[rows[0].lat,rows[0].lng];
  if(!teamMap)teamMap=new ymaps.Map(mapEl,{center,zoom:12,controls:['zoomControl','geolocationControl']});
  teamMarkers.forEach(m=>teamMap.geoObjects.remove(m));teamMarkers=[];
  rows.forEach(w=>{const preset=w.status==='busy'?'islands#violetIcon':w.status==='reserved'?'islands#yellowIcon':'islands#greenIcon';const info='<b>'+esc(w.name)+(w.is_self?' · вы':'')+'</b><br>'+esc(w.vehicle_type)+(w.plate?' · '+esc(w.plate):'')+'<br>'+esc(teamStatusRu(w.status))+(w.distance_km===null||w.is_self?'':'<br>'+w.distance_km+' км · около '+w.eta_min+' мин');const marker=new ymaps.Placemark([w.lat,w.lng],{balloonContent:info},{preset,iconKind:'driver'});teamMap.geoObjects.add(marker);teamMarkers.push(marker)});
  if(rows.length>1)teamMap.setBounds(teamMap.geoObjects.getBounds(),{checkZoomRange:true,zoomMargin:38});else teamMap.setCenter(center,13);
  setTimeout(()=>teamMap.container.fitToViewport(),50);
 }catch(e){stateEl.textContent='Нет связи с картой. Повторите обновление.'}
}
async function resolvePartnerCoords(order){
 if(order.pickup_lat!==null&&order.pickup_lng!==null)return [Number(order.pickup_lat),Number(order.pickup_lng)];
 if(!order.pickup_address)return null;
 try{return await geocodeMapAddress(order.pickup_address)}catch(e){return null}
}
async function drawPartnerMarkers(rows){
 if(typeof ymaps==='undefined')return;
 partnerMarkers.forEach(m=>teamMap&&teamMap.geoObjects.remove(m));partnerMarkers=[];
 for(const order of rows){
  const coords=await resolvePartnerCoords(order);if(!coords)continue;
  if(!teamMap){const mapElement=document.getElementById('teamMap');mapElement.hidden=false;teamMap=new ymaps.Map(mapElement,{center:coords,zoom:12,controls:['zoomControl','geolocationControl']})}
  const status=order.status==='queued'&&order.is_mine?'Следующая после текущей':order.is_mine?'В работе у вас':order.status==='claimed'?'Взял '+esc(order.assigned_worker_name):'Свободна';
  const destination=order.destination||((order.destination_lat!==null&&order.destination_lng!==null)?order.destination_lat+', '+order.destination_lng:'Не указано');
  const content='<b>'+esc(order.service)+'</b><br>Подача: '+esc(order.pickup_address||coords.join(', '))+'<br>Куда: '+esc(destination)+(order.license_plate?'<br>Госномер: <b>'+esc(order.license_plate)+'</b>':'')+(order.service_until?'<br>Сервис работает: '+esc(order.service_until):'')+'<br>'+status;
  const preset=order.is_mine?'islands#greenIcon':order.status==='claimed'?'islands#yellowIcon':'islands#redIcon';
  const marker=new ymaps.Placemark(coords,{balloonContent:content},{preset});teamMap.geoObjects.add(marker);partnerMarkers.push(marker);
 }
 if(teamMap&&teamMap.geoObjects.getLength()>1){const bounds=teamMap.geoObjects.getBounds();if(bounds)teamMap.setBounds(bounds,{checkZoomRange:true,zoomMargin:38})}
}
function partnerStatus(order){if(order.status==='queued'&&order.is_mine)return 'Следующая после текущей';if(order.is_mine)return 'У вас в работе';if(order.status==='claimed')return 'Взял '+(order.assigned_worker_name||'водитель');if(order.chain_target)return 'Приоритет до 12 часов';if(order.urgency==='critical')return 'Критическая';if(order.urgency==='high')return 'Высокий приоритет';return order.chain_rank?'№'+order.chain_rank+' в цепочке':'Свободна'}
function partnerDeadline(order){if(order.deadline_seconds_left===null||order.deadline_seconds_left===undefined)return '';const seconds=Number(order.deadline_seconds_left);if(seconds<=0)return '<div class="partnerDistance">Срок 12 часов превышен</div>';const hours=Math.floor(seconds/3600),minutes=Math.floor((seconds%3600)/60);return `<div class="partnerDistance">До предельного срока: ${hours} ч ${minutes} мин</div>`}
function partnerChainHint(order){const progress=order.chain_progress_km===null||order.chain_progress_km===undefined?'':`<div class="line muted">После выполнения: ${order.chain_progress_km>=0?'приблизит':'удалит'} к приоритетной заявке на ${Math.abs(order.chain_progress_km)} км</div>`;return partnerDeadline(order)+progress}
function partnerAge(minutes){if(minutes===null||minutes===undefined)return 'время неизвестно';minutes=Math.max(0,Number(minutes)||0);const days=Math.floor(minutes/1440),hours=Math.floor((minutes%1440)/60),mins=Math.floor(minutes%60);return 'ожидает '+(days?days+' д ':'')+(hours?hours+' ч ':'')+mins+' мин'}
function partnerDestinationCoords(o){
 const savedLat=Number(o.destination_lat),savedLng=Number(o.destination_lng);
 if(Number.isFinite(savedLat)&&Number.isFinite(savedLng)&&savedLat>=41&&savedLat<=82&&savedLng>=19&&savedLng<=180)return [savedLat,savedLng];
 const text=String(o.destination||'');let found=null;
 for(const m of text.matchAll(/(-?\d{1,2}\.\d+)\s*,\s*(-?\d{1,3}\.\d+)/g)){const lat=Number(m[1]),lng=Number(m[2]);if(lat>=41&&lat<=82&&lng>=19&&lng<=180)found=[lat,lng]}
 return found;
}
async function geocodeMapAddress(address){const response=await fetch('/api/order_map.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'geocode',q:String(address||'')})});const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.error||'Адрес не найден');const coords=[Number(data.lat),Number(data.lng)];if(!Number.isFinite(coords[0])||!Number.isFinite(coords[1]))throw new Error('Некорректные координаты');return coords}
const destinationGeoPending=new Set(),destinationGeoFailed=new Map();
async function ensurePartnerDestination(o){
 if(!o.is_mine||!o.destination||destinationGeoPending.has(o.id))return;
 if(o.destination_lat!==null&&o.destination_lng!==null)return;
 const lastFailure=destinationGeoFailed.get(o.id);if(lastFailure&&Date.now()-lastFailure.time<300000)return;
 destinationGeoPending.add(o.id);
 try{
  let c=partnerDestinationCoords(o);
  if(!c)c=await geocodeMapAddress(o.destination);
  if(!Array.isArray(c)||c.length<2)throw new Error('Адрес точки Б не найден');
  const response=await fetch('api/partner_order_destination.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,order_id:o.id,lat:c[0],lng:c[1]})});
  const data=await response.json().catch(()=>({}));if(!response.ok||!data.ok)throw new Error(data.error||'Не удалось сохранить точку Б');
  destinationGeoFailed.delete(o.id);o.destination_lat=c[0];o.destination_lng=c[1];await loadPartnerOrders();
 }catch(e){destinationGeoFailed.set(o.id,{time:Date.now(),message:e.message||'Адрес не найден'});loadPartnerOrders()}finally{destinationGeoPending.delete(o.id)}
}
async function loadPartnerOrders(){
 if(!OWN_FLEET)return;
 const stateEl=document.getElementById('partnerState'),listEl=document.getElementById('partnerOrders');
 try{
  const r=await fetch('api/partner_orders.php',{cache:'no-store',headers:AUTH_HEADERS}),d=await r.json();
  if(!d.ok){stateEl.textContent=d.error==='OWN_FLEET_ONLY'?'Доступно только нашему парку.':(d.error||'Не удалось загрузить заявки');listEl.innerHTML='';return}
  if(!d.online){stateEl.textContent='Выйдите на линию, чтобы увидеть заявки.';listEl.innerHTML='';await drawPartnerMarkers([]);return}
  const rows=d.orders||[],homeActive=document.getElementById('homePartnerActive'),mine=rows.find(o=>o.is_mine&&['claimed','queued'].includes(o.status));if(homeActive){homeActive.hidden=!mine;if(mine)homeActive.textContent=(mine.status==='queued'?'Следующая заявка MAX / B2B':'Активная заявка MAX / B2B')+' · '+(mine.license_plate||mine.id)+' — открыть'}stateEl.textContent=rows.length?'Заявки выстроены в цепочку к самой старой MAX / B2B.':'Свободных партнёрских заявок сейчас нет.';
  listEl.innerHTML=rows.map(o=>{const destination=o.destination||((o.destination_lat!==null&&o.destination_lng!==null)?o.destination_lat+', '+o.destination_lng:'Не указано');const badge=o.is_overdue?'partnerPriority':o.is_mine?'partnerMine':o.status==='claimed'?'partnerBusy':'';const action=o.status==='queued'&&o.is_mine?`<button class="btn green" onclick="partnerAct('${esc(o.id)}','claim')">Подтвердить следующую</button><button class="btn partnerRelease" onclick="partnerAct('${esc(o.id)}','release')">Отказаться</button>`:o.is_mine?`<button class="btn partnerRelease" onclick="partnerAct('${esc(o.id)}','release')">Вернуть в список</button>`:(o.status==='available'&&o.can_claim)?`<button class="btn green" onclick="partnerAct('${esc(o.id)}','claim')">Взять в работу</button>`:(o.claim_blocked?`<button class="btn" disabled>Сначала приоритетная MAX</button>`:'');const mapLink=o.pickup_lat!==null&&o.pickup_lng!==null?`<a class="btn" style="display:block;text-align:center;text-decoration:none" target="_blank" rel="noopener" href="https://yandex.ru/maps/?ll=${o.pickup_lng}%2C${o.pickup_lat}&z=16&pt=${o.pickup_lng}%2C${o.pickup_lat}%2Cpm2rdm">Маршрут к точке А</a>`:'';const destinationCoords=partnerDestinationCoords(o),geoFailure=destinationGeoFailed.get(o.id);const destinationLink=o.is_mine&&destinationCoords?`<a class="btn green" style="display:block;text-align:center;text-decoration:none" href="yandexnavi://build_route_on_map?lat_to=${destinationCoords[0]}&lon_to=${destinationCoords[1]}">Маршрут к точке Б</a>`:(o.is_mine&&destination!=='Не указано'?`<a class="btn green" style="display:block;text-align:center;text-decoration:none" target="_blank" rel="noopener" href="https://yandex.ru/maps/?text=${encodeURIComponent(destination)}">${geoFailure?'Открыть точку Б по адресу':'Определяем точку Б…'}</a>`:'');const geoMessage=geoFailure?`<div class="line muted">Координаты точки Б пока не определены автоматически. Маршрут можно открыть по адресу.</div>`:'';return `<div class="partnerOrder ${o.is_overdue?'partnerOverdue':''}"><div class="partnerTitle"><div><b>${esc(o.service)}</b>${o.vehicle?' · '+esc(o.vehicle):''}${o.license_plate?' · '+esc(o.license_plate):''}</div><span class="partnerStatus ${badge}">${esc(o.is_overdue?'ПРИОРИТЕТ · '+partnerStatus(o):partnerStatus(o))}</span></div>${o.age_minutes!==null?`<div class="partnerAge">${esc(partnerAge(o.age_minutes))}${o.is_overdue?' · более 12 часов':''}</div>`:''}<div class="routePair"><b>Откуда:</b> ${esc(o.pickup_address||'Координаты на карте')}<br><b>Куда:</b> ${esc(destination)}${o.service_until?'<br><b>Время работы:</b> '+esc(o.service_until):''}</div>${o.distance_km!==null?`<div class="partnerDistance">${o.distance_km} км · примерно ${o.eta_min} мин</div>`:''}${o.comment?`<div class="line muted">${esc(o.comment)}</div>`:''}${geoMessage}<div class="partnerActions">${mapLink}${destinationLink}${action}</div></div>`}).join('');
  listEl.querySelectorAll('.partnerOrder').forEach((card,index)=>card.insertAdjacentHTML('beforeend',partnerChainHint(rows[index]||{})));
  listEl.querySelectorAll('.partnerOrder').forEach((card,index)=>{const order=rows[index];if(order?.is_mine&&order.status==='claimed'){const release=card.querySelector('.partnerRelease');if(release){release.disabled=true;release.removeAttribute('onclick');release.textContent='Снятие только через диспетчера'}}});
  rows.forEach(ensurePartnerDestination);
