}
async function partnerAct(id,action){const r=await fetch('api/partner_order_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,order_id:id,action})}),d=await r.json();if(!d.ok){alert(d.error==='ALREADY_CLAIMED'?'Заявку уже взял '+(d.worker||'другой водитель'):d.error==='OVERDUE_B2B_MAX_PRIORITY'?'Сначала возьмите приоритетную заявку B2B MAX'+(d.priority_order_id?' '+d.priority_order_id:''):d.error==='ACTIVE_ORDER_RELEASE_FORBIDDEN'?'Принятую в исполнение заявку может снять только диспетчер. Свяжитесь с диспетчером.':(d.error||'Не удалось изменить заявку'));return}loadPartnerOrders()}
async function sendLoc(lat,lng,status,accuracy=null){const r=await fetch('api/worker_location.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,lat,lng,status,accuracy})});if(!r.ok)throw new Error('LOCATION_UPDATE_FAILED');return r.json()}
function lineUi(value){const changed=online!==value;online=value;lineBtn.textContent=value?'Уйти с линии':'Выйти на линию';lineBtn.classList.toggle('red',!value);if(changed&&window.AVRPWA)window.AVRPWA.keepAwake(value)}
async function acceptPosition(p){
 coords.textContent=p.coords.latitude.toFixed(5)+', '+p.coords.longitude.toFixed(5)+' · '+Math.round(p.coords.accuracy||0)+' м';
 lastPosition={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy||null};
 const n=Date.now();if(n-lastSent<8000)return online;lastSent=n;
 try{await sendLoc(p.coords.latitude,p.coords.longitude,'online',p.coords.accuracy||null);lineUi(true);load();loadTeamMap();loadPartnerOrders();return true}catch(e){lineUi(false);coords.textContent+=' · координаты получены, но сервер недоступен';return false}
}
function geoErrorText(error){
 if(error?.code===1)return 'Safari запретил доступ к геопозиции для av-rescue.ru. Откройте настройки сайта и разрешите геопозицию.';
 if(error?.code===2)return 'iPhone временно не может определить координаты. Проверьте связь, выйдите на открытое место и повторите.';
 if(error?.code===3)return 'iPhone не успел определить координаты. Нажмите «Выйти на линию» ещё раз.';
 return 'Не удалось определить геопозицию. Проверьте настройки геолокации и повторите.';
}
function getPosition(options){return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,options))}
function finishGeoStart(requestId){if(requestId!==geoRequestId)return false;geoStarting=false;lineBtn.disabled=false;return true}
async function start(silent=false){
 if(geoStarting)return;
 if(!navigator.geolocation){lineUi(false);coords.textContent='Геолокация не поддерживается этим браузером';if(!silent)alert('Геолокация не поддерживается этим браузером');return}
 const requestId=++geoRequestId;geoStarting=true;lineUi(false);lineBtn.disabled=true;lineBtn.textContent='Определяем геопозицию…';coords.textContent='Определяем геопозицию…';
 if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;
 let position=null,lastError=null;
 try{
  try{position=await getPosition({enableHighAccuracy:true,maximumAge:15000,timeout:25000})}catch(error){lastError=error;if(error?.code===1)throw error}
  if(!position)position=await getPosition({enableHighAccuracy:false,maximumAge:120000,timeout:20000});
  if(requestId!==geoRequestId)return;
  const accepted=await acceptPosition(position);
  if(!finishGeoStart(requestId))return;
  if(!accepted){sendLoc('','','offline').catch(()=>{});if(!silent)alert('Координаты получены, но не удалось передать их серверу. Проверьте интернет и повторите.');return}
  watch=navigator.geolocation.watchPosition(p=>{if(requestId===geoRequestId)acceptPosition(p)},error=>{
   if(requestId!==geoRequestId)return;
   if(error?.code===1){lineUi(false);coords.textContent=geoErrorText(error);navigator.geolocation.clearWatch(watch);watch=null;sendLoc('','','offline').catch(()=>{});return}
   coords.textContent='GPS временно недоступен, повторяем поиск координат…';
  },{enableHighAccuracy:true,maximumAge:15000,timeout:30000});
 }catch(error){
  lastError=error||lastError;if(!finishGeoStart(requestId))return;lineUi(false);sendLoc('','','offline').catch(()=>{});coords.textContent=geoErrorText(lastError);if(!silent)alert(geoErrorText(lastError));
 }
}
async function stop(){geoRequestId++;geoStarting=false;lineBtn.disabled=false;lineUi(false);if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;await sendLoc('','','offline');load();loadTeamMap()}
lineBtn.onclick=()=>{if(geoStarting)return;online?stop():start()};
notifyBtn.onclick=async()=>{try{if(!window.AVRPWA)throw new Error('Обновите страницу');await window.AVRPWA.enablePush(TOKEN);notifyBtn.textContent='Уведомления включены';notifyBtn.disabled=true;window.AVRPWA.toast('Уведомления о заказах включены')}catch(e){alert(e.message)}};
