function setDriverOrderTab(tab){if(tab==='closed'){showPanel('history');return}driverOrderTab=tab;document.querySelectorAll('[data-order-tab]').forEach(x=>x.classList.toggle('active',x.dataset.orderTab===tab));renderDriverOrders()}
function driverStatusRu(s){return ({offered:'Свободная заявка',queued:'Следующая заявка',assigned:'Назначена вам',enroute:'Маршрут к точке А',arrived:'Вы на месте',loading:'Идёт погрузка',in_transit:'Маршрут к точке Б'})[s]||s}
