function renderDriverOrders(){if(photoPickerActive)return;const visible=currentOrders.filter(o=>driverOrderTab==='free'?(o.status==='offered'||o.status==='queued'):(o.status!=='offered'&&o.status!=='queued'));orders.innerHTML=visible.length?visible.map(o=>{
    const offered=o.status==='offered'||o.status==='queued';
   const financial=o.offer_financials||null,financialCard=financial&&!financial.excluded?`<div class="financeRules" style="margin-top:10px"><div class="financeRule"><b>Цена заказа</b>${money(financial.price)}</div><div class="financeRule"><b>Ваш доход · ${Number(financial.payout_rate||0).toFixed(1)}%</b>${money(financial.driver_net)}<div class="muted">Комиссия AV Rescue ${money(financial.commission)}</div></div></div>`:(financial&&financial.excluded?'<div class="profileNotice">MAX/B2B: расчёт ведётся отдельно от лицевого счёта AV Rescue.</div>':'');
   const clientLine=o.phone?`<div class="line">Клиент: <a style="color:#ff6b72" href="tel:${esc(o.phone)}">${esc(o.name||'Клиент')} · ${esc(o.phone)}</a></div>`:'';
   const guestPay=!o.client_registered&&o.payment_method!=='cash'&&o.payment_status!=='paid'&&!offered?`<div class="profileNotice"><b>Безналичная оплата гостя</b><div class="muted">Откройте банковскую страницу и покажите клиенту динамический QR СБП. Сумма привязана к заказу.</div><button class="btn green" onclick="openGuestPayment('${esc(o.id)}',this)">Показать QR для оплаты</button></div>`:'';
   let buttons=offered?`<div class="two"><button class="btn green" onclick="act('${esc(o.id)}','accept')">${o.status==='queued'?'Подтвердить следующую':'Принять'}</button><button class="btn" onclick="act('${esc(o.id)}','reject')">Отказаться</button></div>`:workerStageButtons(o);
   const payLabels={cash_due:'Наличные клиенту',unpaid:'Не оплачено',pending:'Ожидает оплаты',pending_3ds:'Подтверждение оплаты',authorized:'Средства зарезервированы',paid:'Оплачено',declined:'Ошибка оплаты',refund_pending:'Возврат обрабатывается',refunded:'Возвращено',partially_refunded:'Частичный возврат',reversed:'Оплата отменена'};
    return `<div class="card ${offered?'offer':''}"><b>${esc(o.id)}</b>${o.is_priority?'<div class="pill" style="color:#ff9b3e;border-color:#ff9b3e">ПРИОРИТЕТ</div>':''}<div class="workState">${esc(driverStatusRu(o.status))}</div><div class="line"><b>${esc(o.service)}</b> · ${esc(o.vehicle_type)}</div>${routeStop(o.address,false)}${o.destination?routeStop(o.destination,true):''}<div class="line"><b>Оплата:</b> ${esc(payLabels[o.payment_status]||((o.payment_method||'cash')==='cash'?'Наличные':'Не оплачено'))} · ${esc((o.payment_method||'cash')==='cash'?'наличные':'карта / СБП')}</div>${clientLine}${o.comment?`<div class="line muted">${esc(o.comment)}</div>`:''}${financialCard}${guestPay}<div class="two">${workerRouteLink(o.lat,o.lng,o.address,'Маршрут к точке А')}${workerRouteLink(o.destination_lat,o.destination_lng,o.destination,'Маршрут к точке Б')}</div>${buttons}</div>`;
 }).join(''):`<div class="empty"><b>${driverOrderTab==='free'?'Свободных заявок сейчас нет':'Назначенных заявок нет'}</b><div class="workHint">${driverOrderTab==='free'?'Список обновляется автоматически.':'Принятые и текущие заявки появятся здесь.'}</div></div>`;restoreLoadingPhotoState();
}
function workerRouteLink(lat,lng,address,label){if(lat&&lng)return `<a class="btn" style="display:block;text-align:center;text-decoration:none" target="_blank" rel="noopener" href="https://yandex.ru/maps/?rtext=~${encodeURIComponent(lat+','+lng)}&rtt=auto">${label}</a>`;if(address)return `<a class="btn" style="display:block;text-align:center;text-decoration:none" target="_blank" rel="noopener" href="https://yandex.ru/maps/?rtext=~${encodeURIComponent(address)}&rtt=auto">${label}</a>`;return ''}
