function workerStageButtons(o){const id=esc(o.id),s=o.status;if(s==='assigned')return `<button class="btn workPrimary" onclick="act('${id}','enroute')">Начать маршрут к точке А</button>`;if(s==='enroute')return `<button class="btn workPrimary" onclick="act('${id}','arrived')">Я на месте</button>`;if(s==='arrived'){const p=o.price_adjustment_pending,t=o.extra_tariffs||{},dc=Number(p?.dollies??o.dollies??0),battery=!!(p?.dead_battery??o.dead_battery),pending=p?.status==='pending';return `<div class="extrasBox"><h4>Дополнительное оборудование</h4><div class="muted">Подкаты ${money(t.dollies||0)} за шт. · бустер АКБ ${money(t.dead_battery||0)}</div><div class="extrasGrid"><label>Подкаты (0–4)<select id="dollies-${id}" ${pending?'disabled':''}>${[0,1,2,3,4].map(n=>`<option value="${n}" ${n===dc?'selected':''}>${n}</option>`).join('')}</select></label><label>Бустер АКБ<div class="extrasCheck"><input id="battery-${id}" type="checkbox" ${battery?'checked':''} ${pending?'disabled':''}><span>Использован</span></div></label></div>${pending?`<div class="extrasState">Ожидается подтверждение клиента: ${money(p.before)} → ${money(p.after)}. Погрузку можно начать после решения.</div>`:`<button class="btn" id="extras-save-${id}" onclick="saveExtras('${id}')">Пересчитать и добавить</button><div class="muted">${o.client_registered?'Клиент получит запрос на подтверждение новой суммы.':'Клиент без аккаунта: новая сумма применится сразу.'}</div>`}</div><div class="photoGrid">${photoInput(id,'front','Спереди')}${photoInput(id,'rear','Сзади')}${photoInput(id,'left','Слева')}${photoInput(id,'right','Справа')}</div><button id="loading-${id}" class="btn workPrimary" ${pending?'disabled':''} onclick="startLoading('${id}')">${pending?'Ожидается решение клиента':'Фото автомобиля и погрузка'}</button>`}if(s==='loading')return `<button class="btn workPrimary" onclick="act('${id}','in_transit')">Погрузка завершена — к точке Б</button>`;if(s==='in_transit')return `<button class="btn workPrimary" onclick="act('${id}','done')">Завершить заявку</button>`;return ''}
async function saveExtras(id){const button=document.getElementById('extras-save-'+id);button.disabled=true;try{const payload={worker_token:TOKEN,order_id:id,dollies:Number(document.getElementById('dollies-'+id).value),dead_battery:document.getElementById('battery-'+id).checked};const r=await fetch('/api/mobile_order_adjustment.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось изменить стоимость');alert(d.approval_required?'Запрос отправлен зарегистрированному клиенту. Дождитесь решения перед погрузкой.':'Допоборудование добавлено. Новая стоимость: '+money(d.estimated_price));await load()}catch(e){alert(e.message||'Не удалось изменить стоимость');button.disabled=false}}
function photoKey(id,side){return id+':'+side}
function photoInput(id,side,title){const ready=loadingPhotoFiles.has(photoKey(id,side));return `<label data-photo-key="${id}:${side}" class="${ready?'photoReady':''}"><b>${title}</b><small>${ready?'✓ Фото выбрано':'Нажмите, чтобы снять'}</small><input id="photo-${side}-${id}" type="file" accept="image/*" capture="environment" onclick="beginPhotoCapture()" onchange="rememberLoadingPhoto('${id}','${side}',this)"></label>`}
function beginPhotoCapture(){photoPickerActive=true;clearTimeout(photoPickerTimer);photoPickerTimer=setTimeout(()=>{photoPickerActive=false},120000)}
function rememberLoadingPhoto(id,side,input){photoPickerActive=false;clearTimeout(photoPickerTimer);const file=input&&input.files&&input.files[0];if(!file)return;loadingPhotoFiles.set(photoKey(id,side),file);restoreLoadingPhotoState()}
function restoreLoadingPhotoState(){document.querySelectorAll('[data-photo-key]').forEach(label=>{const ready=loadingPhotoFiles.has(label.dataset.photoKey);label.classList.toggle('photoReady',ready);const state=label.querySelector('small');if(state)state.textContent=ready?'✓ Фото выбрано':'Нажмите, чтобы снять'})}
function clearLoadingPhotos(id){['front','rear','left','right'].forEach(side=>loadingPhotoFiles.delete(photoKey(id,side)))}
async function act(id,action,extra={}){try{let r=await fetch('api/worker_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,order_id:id,action,...extra})});let d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error==='OVERDUE_B2B_MAX_PRIORITY'?'Сначала возьмите просроченную заявку B2B MAX'+(d.priority_order_id?' '+d.priority_order_id:''):(d.error||'Не удалось изменить статус'));await load()}catch(e){alert(e.message||'Не удалось изменить статус')}}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать фотографию'));reader.readAsDataURL(file)})}
async function optimizedPhotoData(file){if(!file)throw new Error('Фотография не выбрана');const url=URL.createObjectURL(file);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Формат фотографии не поддерживается'));image.src=url});const maxSide=1920,scale=Math.min(1,maxSide/Math.max(image.naturalWidth||image.width,image.naturalHeight||image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((image.naturalWidth||image.width)*scale));canvas.height=Math.max(1,Math.round((image.naturalHeight||image.height)*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Не удалось подготовить фотографию');ctx.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise((resolve,reject)=>canvas.toBlob(x=>x?resolve(x):reject(new Error('Не удалось сжать фотографию')),'image/jpeg',.82));return await fileData(blob)}finally{URL.revokeObjectURL(url)}}
async function startLoading(id){const sides=['front','rear','left','right'],files=sides.map(side=>loadingPhotoFiles.get(photoKey(id,side))||document.getElementById('photo-'+side+'-'+id)?.files?.[0]);if(files.some(file=>!file)){alert('Сделайте четыре фотографии: спереди, сзади, слева и справа');return}const button=document.getElementById('loading-'+id);button.disabled=true;try{const photos=[];for(let i=0;i<sides.length;i++){button.textContent='Загружаем фото '+(i+1)+' из 4…';const kind='order_vehicle_'+sides[i],data=await optimizedPhotoData(files[i]),r=await fetch('/api/mobile_upload.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({worker_token:TOKEN,order_id:id,kind,data})}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось загрузить фотографию '+(i+1));photos.push({side:kind,path:d.path})}button.textContent='Сохраняем статус…';let r=await fetch('api/worker_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,order_id:id,action:'loading',photos})}),d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось начать погрузку');clearLoadingPhotos(id);await load()}catch(e){alert(e.message||'Не удалось начать погрузку');button.disabled=false;button.textContent='Повторить загрузку 4 фото'}}
async function loadFinance(){const box=document.getElementById('financeBox'),ops=document.getElementById('financeOps');try{let r=await fetch('api/worker_finance.php?token='+encodeURIComponent(TOKEN),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось загрузить расчёты');let x=d.summary||{},periods=d.periods||{},loyalty=d.loyalty||{};document.getElementById('financeAvailable').textContent=money(x.available);document.getElementById('homeAvailable').textContent=money(x.available);document.getElementById('financeBalance').textContent='Текущий баланс: '+money(x.current_balance);document.getElementById('financeNextPayout').textContent='Ближайшая выплата: '+esc(x.next_payout_date||'—');document.getElementById('financePeriods').innerHTML=[['Сегодня',periods.today],['Неделя',periods.week],['Месяц',periods.month]].map(v=>`<div class="periodCard"><small>${v[0]} · ${Number(v[1]?.orders||0)} заказов</small><b>${money(v[1]?.earned||0)}</b></div>`).join('');box.innerHTML=[['На проверке '+Number(x.payout_hold_hours||48)+' ч',x.pending],['Ожидает оплаты клиента',x.awaiting_payment],['Зарезервировано на выплату',x.reserved],['Задолженность',x.debt],['Всего заработано',x.earned],['Комиссия AV Rescue',x.commission],['Выплачено',x.paid],['Ваша выплата с заказа',Number(loyalty.payout_rate||0).toFixed(1)+'%']].map(v=>'<div class="metric"><small>'+v[0]+'</small><b>'+(typeof v[1]==='string'?v[1]:money(v[1]))+'</b></div>').join('');document.getElementById('payoutRules').textContent='Выплаты: вторник и пятница · минимум '+money(x.payout_minimum||4000)+' · заявка резервирует сумму до решения';const blockerLabels={debt:'Сначала погасите задолженность по комиссии.',minimum:'Доступная сумма меньше минимальных 4 000 ₽.',request_in_progress:'Предыдущая заявка на выплату ещё обрабатывается.'},blockers=x.payout_blockers||[];document.getElementById('payoutHint').textContent=blockers.length?blockers.map(k=>blockerLabels[k]||k).join(' '):'Можно создать заявку на ближайший платёжный день.';const payoutButton=document.getElementById('payoutButton');payoutButton.disabled=!x.can_request_payout;payoutButton.textContent=x.can_request_payout?'Запросить выплату':'Выплата пока недоступна';let states={available:['Доступно','stateAvailable'],hold:['Проверка 48 часов','stateHold'],awaiting_payment:['Ожидает оплаты клиента','stateAwait'],cash_commission:['Комиссия списана с баланса','stateCash']},methods={cash:'Наличные',online:'Карта / СБП'};let tx=d.transactions||[];ops.innerHTML=tx.length?tx.map(t=>{let state=states[t.finance_state]||[t.finance_state||'Проведено',''];return `<div class="transactionCard"><div class="transactionHead"><b>Заказ ${esc(t.order_id||'—')}</b><b>${money(t.driver_net)}</b></div><div class="transactionLine"><span>Цена заказа</span><span>${money(t.price)}</span></div><div class="transactionLine"><span>${esc(methods[t.payment_method]||t.payment_method)} · комиссия ${Number(t.commission_rate||0).toFixed(1)}%</span><span>−${money(t.commission)}</span></div><div class="transactionLine"><span>Изменение баланса</span><b class="${Number(t.balance_change)>=0?'amountPlus':'amountMinus'}">${Number(t.balance_change)>0?'+':''}${money(t.balance_change)}</b></div><span class="transactionState ${state[1]}">${state[0]}</span>${t.available_at&&t.finance_state==='hold'?`<div class="muted" style="margin-top:6px">Станет доступно: ${dateRu(t.available_at)}</div>`:''}<div class="muted" style="margin-top:6px">Завершён: ${dateRu(t.completed_at)}</div></div>`}).join(''):'<div class="empty">Завершённых заказов пока нет</div>';let labels={new:'На проверке',approved:'Подтверждена главным администратором',processing:'Передана в банк',paid:'Выплачено',failed:'Ошибка выплаты',rejected:'Отклонена'};let ps=d.payouts||[];document.getElementById('financePayouts').innerHTML=ps.length?ps.map(p=>'<div class="ledgerRow"><div><b>Заявка '+esc(p.id)+'</b><div class="muted">'+dateRu(p.created_at)+' · '+esc(labels[p.status]||p.status||'')+(p.scheduled_for?' · план '+esc(p.scheduled_for):'')+(p.status_note?' · '+esc(p.status_note):'')+'</div></div><b>'+money(p.amount)+'</b></div>').join(''):'<div class="empty">Выплат пока нет</div>'}catch(e){box.innerHTML='<span class="muted">'+esc(e.message||'Не удалось загрузить расчёты')+'</span>';ops.innerHTML=''}}
let savedPayoutAccount=null;
function togglePayoutAccount(force){const form=document.getElementById('payoutAccountForm');form.hidden=force===undefined?!form.hidden:!force;if(!form.hidden)togglePayoutFields()}
function togglePayoutFields(){const method=document.getElementById('payoutMethod').value;document.querySelectorAll('.payoutField').forEach(x=>x.hidden=x.dataset.method!==method)}
async function loadPayoutAccount(){try{let r=await fetch('api/payout_account.php?token='+encodeURIComponent(TOKEN),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось загрузить реквизиты');savedPayoutAccount=d.account||null;const s=document.getElementById('payoutAccountState');s.textContent=savedPayoutAccount&&savedPayoutAccount.ready?(savedPayoutAccount.method_label+' · '+savedPayoutAccount.account_mask):'Способ выплаты ещё не настроен';if(savedPayoutAccount){document.getElementById('payoutMethod').value=savedPayoutAccount.method||'sbp';document.getElementById('payoutHolder').value=savedPayoutAccount.holder_name||'';document.getElementById('payoutBankName').value=savedPayoutAccount.bank_name||''}togglePayoutFields();if(!savedPayoutAccount||!savedPayoutAccount.ready)togglePayoutAccount(true)}catch(e){document.getElementById('payoutAccountState').textContent=e.message}}
async function savePayoutAccount(){const button=document.getElementById('payoutAccountSave'),method=document.getElementById('payoutMethod').value;button.disabled=true;try{const payload={token:TOKEN,method,holder_name:document.getElementById('payoutHolder').value,bank_name:document.getElementById('payoutBankName').value,phone:document.getElementById('payoutPhone').value,bank_account:document.getElementById('payoutBankAccount').value,bik:document.getElementById('payoutBik').value};let r=await fetch('api/payout_account.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось сохранить реквизиты');togglePayoutAccount(false);await loadPayoutAccount();await loadFinance();alert('Способ выплаты сохранён')}catch(e){alert(e.message||'Ошибка');button.disabled=false}}
async function requestPayout(){const amount=document.getElementById('payoutAmount'),button=document.getElementById('payoutButton');if(!savedPayoutAccount||!savedPayoutAccount.ready){alert('Сначала сохраните способ выплаты');togglePayoutAccount(true);return}button.disabled=true;try{let r=await fetch('api/request_payout.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:TOKEN,amount:+amount.value})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось создать заявку');alert('Заявка '+d.payout_id+' создана на '+money(+amount.value));amount.value='';await loadFinance();await loadLedger()}catch(e){alert(e.message||'Ошибка выплаты');button.disabled=false}}
async function restoreWorkerAfterResume(){await load();if(currentOrders.some(o=>['offered','queued','assigned','enroute','arrived','loading','in_transit'].includes(o.status)))showPanel('jobs');loadFinance();if(online){if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;lastSent=0;start(true)}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')restoreWorkerAfterResume()});
window.addEventListener('focus',()=>setTimeout(()=>{photoPickerActive=false},1500));
window.addEventListener('pageshow',()=>restoreWorkerAfterResume());
load();loadFinance();loadPayoutAccount();if(OWN_FLEET){if(typeof ymaps!=='undefined')ymaps.ready(()=>{loadTeamMap();loadPartnerOrders()});else{loadTeamMap();loadPartnerOrders()}AVPoll.every(loadTeamMap,20000,60000);AVPoll.every(loadPartnerOrders,15000,45000)}AVPoll.every(load,10000,30000);setInterval(()=>{if(online&&lastPosition)sendLoc(lastPosition.lat,lastPosition.lng,'online',lastPosition.accuracy).catch(()=>{})},20000);AVPoll.every(loadFinance,30000,90000);
</script>

<script>
async function loadLedger(){const box=document.getElementById('financeLedger');try{let r=await fetch('/api/driver_ledger.php?token='+encodeURIComponent(TOKEN),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error();let rows=d.ledger||[];box.innerHTML=rows.length?rows.map(x=>{let amount=Number(x.amount??x.sum??0),state=x.availability_state==='hold'?' · проверка до '+dateRu(x.available_at):'';return '<div class="ledgerRow"><div><b>'+esc(x.label||x.type||'Операция')+'</b><div class="muted">'+dateRu(x.created_at||x.date||'')+(x.order_id?' · '+esc(x.order_id):'')+state+'</div></div><b class="'+(amount>=0?'amountPlus':'amountMinus')+'">'+(amount>0?'+':'')+money(amount)+'</b></div>'}).join(''):'<div class="empty">Операций пока нет</div>'}catch(e){box.innerHTML='<div class="muted">Не удалось загрузить операции</div>'}}
loadLedger();AVPoll.every(loadLedger,30000,90000);
</script></body></html>
